public class Main {
    public static void main(String[] args) {
        int score = 10; //~ Make a box called score, of type int (whole numbers), and put 10 in it.
        score = score + 5; //~ Read score (10), add 5, and store the 15 back in the same box.
        String name = "Asha"; //~ A String holds text. Text always goes inside double quotes.
        System.out.println(name + " scored " + score); //~ + joins text: "Asha" + " scored " + 15.
    }
}

